    n = len(grid)
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # dp_prev[i][j] = lexicographically minimum tuple of length t-1
    # starting from cell (i, j)
    dp_prev = [[(grid[i][j],) for j in range(n)] for i in range(n)]

    for t in range(2, k + 1):
        dp_cur = [[None] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                best_next = None
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        cand = dp_prev[ni][nj]
                        if best_next is None or cand < best_next:
                            best_next = cand
                dp_cur[i][j] = (grid[i][j],) + best_next
        dp_prev = dp_cur

    ans = None
    for i in range(n):
        for j in range(n):
            cand = dp_prev[i][j]
            if ans is None or cand < ans:
                ans = cand

    return list(ans)

