def Strongest_Extension(class_name, extensions):
    def strength(ext):
        cap = sum(1 for c in ext if c.isupper())
        sm = sum(1 for c in ext if c.islower())
        return cap - sm

    best = extensions[0]
    best_strength = strength(best)

    for ext in extensions[1:]:
        s = strength(ext)
        if s > best_strength:
            best_strength = s
            best = ext

    return class_name + "." + best

